//! gRPC server reflection for the Rerun services.
//!
//! Serving reflection lets generic gRPC tooling (`grpcurl`, `grpcui`, Postman, …) discover
//! the Rerun services and their message types without access to the `.proto` files.

use tonic::service::Routes;
use tonic_reflection::server::{Builder, v1, v1alpha};

pub use tonic_reflection::server::Error;

/// Encoded `FileDescriptorSet` covering every `rerun.*.v1alpha1` proto file and its imports.
///
/// Generated by `pixi run codegen-protos` alongside the Rust types.
pub const FILE_DESCRIPTOR_SET: &[u8] = include_bytes!("v1alpha1/rerun.v1alpha1.fds.bin");

/// The `v1` and `v1alpha` reflection services for a server that serves `served_services`.
///
/// Both protocol versions are served, because clients differ in which one they speak: recent
/// `grpcurl` probes `v1` first and falls back to `v1alpha`, while older tooling only knows `v1alpha`.
///
/// `served_services` are the fully-qualified names of the services the caller serves on this
/// port, i.e. their [`tonic::server::NamedService::NAME`]. Only these are returned by a
/// `list` request, so clients can tell what an address speaks. Symbol lookups still cover the
/// full Rerun protocol, so every message type can be described.
pub fn services<'a>(
    served_services: impl IntoIterator<Item = &'a str>,
) -> Result<
    (
        v1::ServerReflectionServer<impl v1::ServerReflection>,
        v1alpha::ServerReflectionServer<impl v1alpha::ServerReflection>,
    ),
    Error,
> {
    let served_services: Vec<&str> = served_services.into_iter().collect();
    // `with_service_name` disables the automatic listing of the reflection service itself,
    // so each protocol version advertises its own service explicitly, like tonic does by default.
    let configure = |reflection_service: &str| {
        let mut builder = Builder::configure()
            .register_encoded_file_descriptor_set(FILE_DESCRIPTOR_SET)
            .with_service_name(reflection_service);
        for service in &served_services {
            builder = builder.with_service_name(*service);
        }
        builder
    };
    let v1 = configure("grpc.reflection.v1.ServerReflection").build_v1()?;
    let v1alpha = configure("grpc.reflection.v1alpha.ServerReflection").build_v1alpha()?;
    Ok((v1, v1alpha))
}

/// Adds gRPC server reflection to `routes`, listing `served_services`.
///
/// See [`services`].
pub fn with_reflection<'a>(
    routes: Routes,
    served_services: impl IntoIterator<Item = &'a str>,
) -> Result<Routes, Error> {
    let (v1, v1alpha) = services(served_services)?;
    Ok(routes.add_service(v1).add_service(v1alpha))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn descriptor_set_builds_reflection_services() {
        with_reflection(Routes::default(), []).expect("the checked-in descriptor set must decode");
    }

    #[test]
    fn descriptor_set_lists_all_services() {
        use prost::Message as _;
        let fds = prost_types::FileDescriptorSet::decode(FILE_DESCRIPTOR_SET)
            .expect("the checked-in descriptor set must decode");
        let mut services: Vec<String> = fds
            .file
            .iter()
            .flat_map(|file| {
                let package = file.package.clone().unwrap_or_default();
                file.service
                    .iter()
                    .map(move |service| format!("{package}.{}", service.name()))
            })
            .collect();
        services.sort();
        assert_eq!(
            services,
            [
                "rerun.cloud.v1alpha1.RerunCloudService",
                "rerun.sdk_comms.v1alpha1.MessageProxyService",
                "rerun.sdk_comms.v1alpha1.ViewerControlService",
            ]
        );
    }
}
